{"code":"from collections import deque
# pass map from centers current; specials pass
import arclog
b=arclog.load()[-1].board
P={(c,r) for r in range(10) for c in range(10) if int(b[7+5*r,11+5*c])!=4}
launch={(7,3):(7,8),(5,3):(9,3),(7,4):(5,4),(6,4):(6,0),(2,6):(2,8),(0,6):(3,6),(3,7):(0,7),(7,7):(5,7)}
dirs=[('U',(0,-1)),('D',(0,1)),('L',(-1,0)),('R',(1,0))]
def trans(p,ch):
 d=dict(dirs)[ch];q=(p[0]+d[0],p[1]+d[1])
 if q not in P:return None
 return launch.get(q,q)
def shortest(src,dst):
 q=deque([src]);par={src:None};pa={}
 while q:
  p=q.popleft()
  if p==dst:
   acts=[]; poses=[]
   while par[p] is not None: poses.append(p);acts.append(pa[p]);p=par[p]
   return len(acts),''.join(reversed(acts)),list(reversed(poses))
  for ch,_ in dirs:
   z=trans(p,ch)
   if z is not None and z not in par:par[z]=p;pa[z]=ch;q.append(z)
 return None
pois={'S':(9,0),'C':(5,5),'B':(3,5),'Q1':(2,2),'Q2':(5,9),'G':(0,0)}
print('pass map')
for r in range(10):print(''.join('.' if (c,r) in P else '#' for c in range(10)))
for n,p in pois.items():
 print('\nfrom',n,p)
 for m,z in pois.items():print(' to',m,shortest(p,z))
